// 1x1 white WebP (smallest valid VP8L)
const TINY_WEBP_B64 =
	"UklGRiQAAABXRUJQVlA4IBgAAAAwAQCdASoBAAEAAUAmJaQAA3AA/vuUAAA=";

// 1x1 white JPEG
const TINY_JPEG_B64 =
	"";

function decode(b64: string): Buffer {
	return Buffer.from(b64, "base64");
}

export const TINY_WEBP_BYTES = decode(TINY_WEBP_B64);
export const TINY_JPEG_BYTES = decode(TINY_JPEG_B64);
